insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m4.q1', 'm4', 'single', 'm4.1', 'What is the difference between a .gltf and a .glb file?', null, '["A .glb packs the JSON, binary data and textures into one file; a .gltf keeps them in separate files","A .glb is a 2D picture of the model","A .gltf can''t contain animations","They are completely different formats"]'::jsonb, 'The b stands for binary.', '0'::jsonb, '["Correct: same glTF data, but .glb is one binary file: one path, one download.","Both hold real 3D data. Neither is a picture.","glTF supports animations in both forms.","They are the same format (glTF 2.0) packaged differently."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m4.q2', 'm4', 'single', 'm4.1', 'Which file format is designed for 3D on the web?', null, '[".fbx",".obj",".glb (glTF)",".psd"]'::jsonb, 'Often called the JPEG of 3D.', '2'::jsonb, '[".fbx is common in game and animation tools, but heavy and not built for the web.",".obj is old and simple: no animations, materials in a separate file.","Correct: glTF is often called \"the JPEG of 3D\".",".psd is a Photoshop image, not a 3D model."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m4.q3', 'm4', 'single', 'm4.2', 'Where do you import GLTFLoader from?', null, '["''three/addons/loaders/GLTFLoader.js''","''three'' (it''s part of the main file)","''gltf''","It''s built into the browser"]'::jsonb, 'It''s an add-on, not part of the core.', '0'::jsonb, '["Correct: it''s an add-on, so your import map also needs a \"three/addons/\" entry.","GLTFLoader isn''t in the main three.module.js file; it''s an add-on.","There''s no package called ''gltf'' in your import map.","Browsers don''t understand glTF on their own; Three.js''s loader reads it."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m4.q4', 'm4', 'single', 'm4.2', 'In loader.load(path, onLoad), which object do you add to the scene?', null, '["gltf","gltf.scene","gltf.animations","loader"]'::jsonb, 'The results object has a property that is the model itself.', '1'::jsonb, '["gltf is a plain object holding the results; adding it gives \"object not an instance of THREE.Object3D\".","Correct: gltf.scene is the 3D model (a Group).","Those are animation clips, played with an AnimationMixer.","The loader downloads the file. It isn''t a 3D object."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m4.q5', 'm4', 'single', 'm4.2', 'Spot the bug. The console says: Cannot read properties of undefined (reading ''rotation'').', '1  let model;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m4.q6', 'm4', 'single', 'm4.3', 'Your page is index.html, your code is in js/bg.js and your model is assets/robot.glb. Which path do you pass to loader.load()?', null, '["''../assets/robot.glb''","''assets/robot.glb''","''/js/assets/robot.glb''","''C:/portfolio/assets/robot.glb''"]'::jsonb, 'Paths are relative to the page.', '1'::jsonb, '["That''s relative to bg.js, but the browser resolves paths against the page.","Correct: relative to index.html, which sits next to the assets folder.","The model isn''t inside js/, and a leading slash breaks on GitHub Pages project sites.","That''s a path on your own computer; visitors can''t reach it."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m4.q7', 'm4', 'single', 'm4.3', 'The model loads on your Windows laptop but is a 404 on GitHub Pages. The file is Robot.glb and the code loads ''assets/robot.glb''. Why?', null, '["GitHub Pages is case-sensitive: Robot.glb and robot.glb are different files","GitHub Pages doesn''t support .glb files","The model is too big for GitHub","GitHub Pages needs a leading slash"]'::jsonb, 'R vs r.', '0'::jsonb, '["Correct: Windows ignores capitals, the web doesn''t. Match the name exactly.","GitHub Pages serves .glb files like any other file.","Size would make it slow, not a 404.","A leading slash would point outside your project site."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m4.q8', 'm4', 'single', 'm4.3', 'You double-click index.html and the model won''t load (a CORS error in the console). What''s the fix?', null, '["Open the page through a local server, e.g. VS Code''s Live Server","Rename the model to .gltf","Add more lights","Move the model into the js folder"]'::jsonb, 'Look at the address bar: file://…', '0'::jsonb, '["Correct: browsers block loading files from file:// pages. A local server serves them over http.","The format isn''t the problem; file:// is.","Lights don''t affect whether the file can be downloaded.","The folder doesn''t matter; the browser blocks file:// loads anywhere."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m4.q9', 'm4', 'single', 'm4.4', 'Which line makes the model twice as big in every direction?', null, '["model.scale.setScalar(2)","model.position.set(2, 2, 2)","model.rotation.y = 2","model.size = 2"]'::jsonb, 'Scale, not position.', '0'::jsonb, '["Correct: the same as model.scale.set(2, 2, 2).","That moves the model; its size doesn''t change.","That turns it by 2 radians (about 115°).","Three.js objects have no size property; use scale."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m4.q10', 'm4', 'single', 'm4.4', 'You want to turn the model to face the other way (180°). Which line is correct?', null, '["model.rotation.y = 180","model.rotation.y = Math.PI","model.rotation.x = Math.PI","model.position.y = Math.PI"]'::jsonb, 'Radians, around the vertical axis.', '1'::jsonb, '["Rotation is in radians: 180 radians is about 28.6 full turns.","Correct: π radians = 180°. (Or THREE.MathUtils.degToRad(180).)","Turning around x flips it upside down.","That moves it up by 3.14 units."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m4.q11', 'm4', 'order', 'm4.5', 'Put these lines in order to play the model''s Wave animation.', null, '["mixer.update(delta);   // inside the animation loop","const mixer = new THREE.AnimationMixer(gltf.scene);","const clip = THREE.AnimationClip.findByName(gltf.animations, ''Wave'');","mixer.clipAction(clip).play();"]'::jsonb, 'Each line uses something the one before it created.', '[1,2,3,0]'::jsonb, '["Create the mixer for the model, find the clip, start its action, then update the mixer every frame so the animation moves."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m4.q12', 'm4', 'single', 'm4.5', 'Which line in your animation loop spins the model on its Y axis, the same speed on every screen?', null, '["if (model) model.rotation.y += 0.6 * delta;","model.rotation.y = 0.6;","model.position.y += 0.6 * delta;","if (model) model.scale.y += 0.6;"]'::jsonb, 'Add to the rotation every frame, scaled by delta.', '0'::jsonb, '["Correct: it adds a little every frame, scaled by delta time, and waits for the model to load.","That sets one fixed angle, so the model stops instead of spinning.","That moves it upward, forever.","That stretches it taller every frame."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
